use std::{fs,path::Path,collections::HashSet};
fn read(p:&Path)->serde_json::Value {if p.exists(){serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}else{serde_json::json!([])}}
fn main(){let root=std::env::args().nth(1).unwrap();let root=Path::new(&root);let mut entries:Vec<_>=fs::read_dir(root.join("corpus/mx")).unwrap().map(|x|x.unwrap().path()).filter(|p|p.join("instrument.json").exists()).collect();entries.sort();let corpora:Vec<serde_json::Value>=entries.iter().map(|p|serde_json::json!({"instrument":read(&p.join("instrument.json")),"provisions":read(&p.join("provisions.json")),"references":read(&p.join("references.json")),"terms":read(&p.join("terms.json")),"term_usages":read(&p.join("term-usages.json")),"amendment_references":read(&p.join("amendment-references.json")),"enactment_evidence":read(&p.join("enactment-evidence.json"))})).collect();let targets:HashSet<String>=corpora.iter().flat_map(|c|c["provisions"].as_array().unwrap().iter().map(|p|p["id"].as_str().unwrap().to_owned())).collect();let terms:HashSet<String>=corpora.iter().flat_map(|c|c["terms"].as_array().unwrap().iter().map(|p|p["id"].as_str().unwrap().to_owned())).collect();let mut configs=std::collections::HashMap::new();for dir in fs::read_dir(root.join("adapters")).unwrap(){let dir=dir.unwrap().path();if !dir.is_dir(){continue}for p in fs::read_dir(dir).unwrap(){let p=p.unwrap().path();if p.extension().is_some_and(|x|x=="json") && !p.file_name().unwrap().to_string_lossy().starts_with('_'){let config=lex_source::load_config(&p).unwrap();configs.insert(config.slug.clone(),config);}}}let mut rows=vec![];for (p,c) in entries.iter().zip(&corpora){let slug=p.file_name().unwrap().to_str().unwrap();let cfg=&configs[slug];let provisions:Vec<_>=serde_json::from_value(c["provisions"].clone()).unwrap();let references:Vec<_>=serde_json::from_value(c["references"].clone()).unwrap();let terms_local:Vec<_>=serde_json::from_value(c["terms"].clone()).unwrap();let usages:Vec<_>=serde_json::from_value(c["term_usages"].clone()).unwrap();let amendments:Vec<_>=serde_json::from_value(c["amendment_references"].clone()).unwrap();let r=lex_parse::validate_corpus(&lex_parse::CorpusView{instrument_id:c["instrument"]["id"].as_str().unwrap(),official_title:c["instrument"]["official_title"].as_str(),provisions:&provisions,references:&references,terms:&terms_local,term_usages:&usages,amendment_references:&amendments},&lex_parse::CorpusExpectations{min_articles:cfg.expected_min_articles,articles:cfg.expected_articles,transitories:cfg.expected_transitories,annexes:cfg.expected_annexes,require_chapter_context:cfg.parser=="ifpe-dcg",allow_article_gaps:cfg.allow_article_gaps},&targets,&terms);rows.push(serde_json::json!({"slug":slug,"report":r}));}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}
